"""Run the whole analysis without opening the notebook.

Ana kont keeping this file intentionally tiny: it is just a convenient start
button, while the real logic stays in ``src/f1podium/pipeline.py``.
"""

from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1]
# The package uses a src/ layout, so a direct script run needs this local path.
sys.path.insert(0, str(ROOT / "src"))
from f1podium.pipeline import run_analysis

if __name__ == "__main__":
    # Everything generated by the analysis goes under artifacts/; momken delete
    # that folder at any time because this call rebuilds it.
    result = run_analysis(ROOT / "data" / "raw", ROOT / "artifacts")
    print(result["metrics"].to_string(index=False))
    print(result["summary"])

